package ioswacontacts_test

import (
	"testing"

	"github.com/rbenzing/minutiae/internal/parsers/ioswacontacts"
	"github.com/rbenzing/minutiae/internal/parsers/parsertest"
)

// The scenario oracle is generated by tools/fixtures/whatsapp_ios_contacts.py from the spec's rules (a second reading, 4I2-R13):
// every record, warning (in the order PF13a states: the mapping's row warnings, then the reader's) and note it states is what
// Parse produces. A variant reported unparsed (another app's database) states no app and is covered by the probe tests.
func TestIOSWhatsAppContactsMatchesOracle(t *testing.T) {
	parsed := 0
	for _, v := range variants {
		fx := parsertest.LoadFixture(t, "testdata", v)
		if fx.Expect.Notes["app"] == "" {
			continue
		}
		parsed++
		t.Run(v, func(t *testing.T) {
			h := parsertest.NewHarness(t)
			b := bundleOf(h, fx, v)
			p := ioswacontacts.Parser{}
			res := h.RunLenient(p, b.Input(h, p, false))
			parsertest.AssertMatchesOracle(t, res, b, fx.Expect)
			if res.Refused != 0 {
				t.Errorf("%d records refused", res.Refused)
			}
		})
	}
	if parsed != len(parsedVariants) {
		t.Errorf("%d variants are parsed, want %d", parsed, len(parsedVariants))
	}
}
